/* snd_driver.c: the sound driver of unit RES03 on the CoCo 3, the PC speaker's tunes only (step 8.8). GENERATED by tools/mksnd.py from
 * c/driver/res03_driver.c (the host build, a port of the original's RES03.ASM proven against the oracle's hardware trace): the tune
 * table, the streams and the voice stepper are that file's text. What the script changes:
 *
 *   - the Tandy chip is not supported (no GMC and no Tandy backend, by decision of the user for step 8.8): the Tandy rows of the tune table,
 *     TandyNotes, TandyQuiet and DriverTandyStep are gone and SetTandyTune keeps CurrentTune as the original does;
 *   - the PC speaker is the CoCo's 6 bit DAC: snd_want_tone(divisor, gate bits) and snd_want_off() are snd_core.c's, which note what the tick wants and let the pump set it in the hardware, turning the
 *     PIT divisor into the GIME timer's reload and let the FIRQ write the square wave to the DAC (src/engine/snd.asm);
 *   - the timer interrupt's body, TimerHandler, is DriverTick: the FIRQ only counts, the pump (snd_core.c, called from the clock and the
 *     keyboard poll) runs DriverTick for every 236.7 Hz tick that has passed;
 *   - the variables are fields of the block snd_state points to (SndState in snd.h): a bank holds no variables, the block is in the
 *     mapped heap.
 * Read the host file for the commentary on the format of the streams. Compiled by CMOC into the sound bank (and into the engine test
 * t_snd) and by clang for the reference run (probes/snd_ref.c). */
#include "snd.h"

/* ---- voice record fields (byte offsets, RES03.ASM) ---- */
enum {
  vCount = 0x00,      /* ticks left in the current event; the stepper skips a voice at 0 */
  vStream = 0x02,     /* the voice's stream pointer, 0 when it has none */
  vPitch = 0x04,      /* period before vibrato */
  vPitchStep = 0x06,  /* added to vPitch every tick (portamento) */
  vOutput = 0x08,     /* the period sent to the device */
  vLevel = 0x0A,      /* level accumulator: speaker gate bits are its low two bits, Tandy attenuation its high nibble inverted */
  vLevelStep = 0x0C,  /* added to vLevel every tick */
  vTempo = 0x0E,      /* multiplies note durations (the note event path) */
  vField10 = 0x10,    /* set to 12 by four streams; nothing reads it */
  vTranspose = 0x12,  /* added to a note number */
  vRelease = 0x14,    /* ticks until the release part of the envelope starts, 0 = never */
  vEnvelope = 0x16,   /* pointer to the envelope table */
  vEnvPos = 0x18,     /* offset of the next envelope entry */
  vEnvCount = 0x1A,   /* ticks left of the current envelope entry */
  vVibrato = 0x1C,    /* pointer to the vibrato table */
  vVibPos = 0x1E,     /* position in it, in sixteenths of an entry */
  vVibStep = 0x20,    /* added to vVibPos every tick (0 = no vibrato) */
  vVibDepth = 0x22,   /* multiplier of the table value */
  vVibLength = 0x24   /* vVibPos wraps at this */
};
/* 26h and 28h are the repeat counters the streams' OpLoop uses; any field may be used. */

/* ---- stream opcodes: the bytes 0FAh..0FFh; anything below is a note event ---- */
enum {
  OpClear = 0xFA,   /* clear the current voice's slopes, envelope and vibrato */
  OpReturn = 0xFB,  /* return from the one-level call */
  OpCall = 0xFC,    /* t: call */
  OpVoice = 0xFD,   /* o: the current voice becomes the record at VoiceBase + o, then it is cleared */
  OpLoop = 0xFE,    /* f t: repeat counter in field f, jump to t */
  OpSet = 0xFF      /* f w: set the word of field f; field 0 ends the burst */
};

enum {
  VoiceWords = 24,                     /* a voice record is 30h bytes */
  VoicesPerDevice = 8,                 /* room for eight records per device, the stepper runs four */
  SteppedVoices = 4,
  TuneRows = 21,                       /* tunes 0..20; row 0 is silence */
  NoteTableSize = 12
};

#define VF(v, off) ((v)[(off) >> 1])

/* The note tables: one octave of periods, 1,193,182 / frequency (SpeakerNotes at 0x01D6 in RES03.ASM), and for the
   Tandy chip (TandyNotes at 0x0370) the same periods scaled to 16 bits (the chip takes the value >> 6). Only the
   dead note-event path reads them. The Tandy table is not on the CoCo. */
static const u16 SpeakerNotes[12] = {
  0x8E84, 0x8684, 0x7EF7, 0x77D7, 0x714F, 0x6AC4,
  0x64C6, 0x5F1E, 0x59C7, 0x54BD, 0x4FFC, 0x4B7E
};

/* The tune table: row Tune holds the stream pointers of voices 0..3 (0 = no stream). 21 rows for the PC speaker
   (SpeakerTunes at 0x0388 in RES03.ASM; the 21 Tandy rows that follow it there are not on the CoCo). Pointers are offsets
   into the file RES03.ASM assembles to; SoundData holds the bytes they point to, starting at SOUND_DATA_BASE. */
