/* ---- the driver's variables: fields of the block snd_state points to (snd.h) ---- */
#define VoiceMem (snd_state->voices)
#define SpeakerVoices (VoiceMem)
#define InService (snd_state->in_service)
#define VoicesLeft (snd_state->voices_left)
#define CurrentTune (snd_state->current_tune)
#define CurrentVoice (snd_state->current_voice)
#define VoiceBase (snd_state->voice_base)
#define NoteTable (snd_state->note_table)
#define ReturnPtr (snd_state->return_ptr)
#define VoiceTune (snd_state->voice_tune)
#define OutputOn (snd_state->output_on)
#define LoudestVoice (snd_state->loudest_voice)

/* A byte or word of SoundData, by the pointer a stream, envelope or vibrato field holds. The original read whatever
   memory such a pointer named; a pointer outside SoundData reads 0 here (no shipped tune has one). */
static u8 DataByte(u16 p)
{
  u16 i = (u16)(p - SOUND_DATA_BASE);
  return i < SOUND_DATA_SIZE ? SoundData[i] : 0;
}

static u16 DataWord(u16 p)
{
  return (u16)(DataByte(p) | ((u16)DataByte((u16)(p + 1)) << 8));
}

/* The voice at VoiceBase + byte offset Offset (OpVoice). */
static Voice *SelectVoice(u16 Offset)
{
  u16 index = (u16)(Offset >> 1);
  if (index >= VoicesPerDevice * VoiceWords) {
    index = 0;
  }
  return VoiceBase + index;
}

/* 08AE:164E. The "clear" of OpClear and OpVoice: the slopes, envelope and vibrato fields. */
static void ClearVoice(Voice *v)
{
  VF(v, vPitch) = 0;
  VF(v, vPitchStep) = 0;
  VF(v, vOutput) = 0;
  VF(v, vLevel) = 0;
  VF(v, vLevelStep) = 0;
  VF(v, vField10) = 0;
  VF(v, vTranspose) = 0;
  VF(v, vEnvelope) = 0;
  VF(v, vEnvPos) = 0;
  VF(v, vEnvCount) = 0;
  VF(v, vVibrato) = 0;
  VF(v, vVibPos) = 0;
  VF(v, vVibStep) = 0;
  VF(v, vVibDepth) = 0;
  VF(v, vVibLength) = 0;
}

/* NextNote/Note: one note event of three bytes (voice<<5 and flags, note with bit 7 = last of the chord, duration).
   `*pdi` points at the note byte on entry and past the event on return; the result is nonzero for the last event.
   No shipped tune has one: this path is the original's, kept as it is. */
static int NoteEvent(Voice *si, u8 first, u16 *pdi)
{
  u16 ev = *pdi;
  u8 voiceNo = (u8)(first >> 5);
  Voice *target = VoiceBase + voiceNo * VoiceWords;
  u8 tempo = (u8)VF(si, vTempo);
  u16 duration;
  u16 note;

  duration = tempo > 1 ? (u16)((u16)tempo * DataByte((u16)(ev + 1))) : DataByte((u16)(ev + 1));
  VF(si, vCount) = duration;
  note = DataByte(ev) & 0x7F;
  if (note != 0x7F && voiceNo == 0) {
    u16 octave;
    VF(target, vCount) = duration;
    VF(target, vRelease) = duration;
    note = (u16)(note + VF(target, vTranspose));
    VF(target, vEnvPos) = 0;
    VF(target, vEnvCount) = 1;
    octave = (u16)(note / 12);
    note = (u16)(note % 12);
    note = NoteTable[note];
    note = octave < 16 ? (u16)(note >> octave) : 0;
    VF(target, vPitch) = note;
    VF(target, vOutput) = note;
  }
  *pdi = (u16)(ev + 2);
  return (DataByte(ev) & 0x80) != 0;
}

/* 08AE:160B RunStream in RES03.ASM. Execute the voice's stream from vStream until it waits (field 0 written). */
static void DriverRunStream(Voice *voice)
{
  Voice *si = voice;
  u16 di = VF(si, vStream);
  u8 op;

  if (di == 0) {
    return;
  }
  CurrentVoice = si;
  for (;;) {
    op = DataByte(di++);
    if (op < OpClear) {
      while (!NoteEvent(si, op, &di)) {
        op = DataByte(di++);
      }
      break;
    }
    switch (op) {
    case OpLoop:
    {
      u8 field = DataByte(di++);
      u16 target = DataWord(di);
      di += 2;
      if (VF(si, field) == 0) {
        di = target;
      } else {
        VF(si, field)--;
        if (VF(si, field) != 0) {
          di = target;
        }
      }
      break;
    }
    case OpVoice:
      si = SelectVoice(DataWord(di));
      di += 2;
      ClearVoice(si);
      break;
    case OpClear:
      ClearVoice(si);
      break;
    case OpSet:
    {
      u8 field = DataByte(di++);
      VF(si, field) = DataWord(di);
      di += 2;
      if (field == 0) {
        goto EventEnd;
      }
      break;
    }
    case OpReturn:
      di = ReturnPtr;
      break;
    default:  /* OpCall */
      ReturnPtr = (u16)(di + 2);
      di = DataWord(di);
      break;
    }
  }
EventEnd:
  /* 08AE:168F. Save the stream pointer in the stepping voice; a voice whose count is 0 is finished. */
  si = CurrentVoice;
  if (VF(si, vCount) == 0) {
    VoiceTune[SteppedVoices - VoicesLeft] = 0;
    di = 0;
  }
  VF(si, vStream) = di;
}

/* 08AE:157A StepVoice in RES03.ASM. One tick of a voice: level and pitch slopes, vibrato, output period, release delay, event
   countdown (DriverRunStream at zero), envelope. */
static void DriverStepVoice(Voice *si)
{
  u16 ax;
  u16 dx = 0;

  VF(si, vLevel) = (u16)(VF(si, vLevel) + VF(si, vLevelStep));
  VF(si, vPitch) = (u16)(VF(si, vPitch) + VF(si, vPitchStep));
  ax = (u16)(VF(si, vVibPos) + VF(si, vVibStep));
  if (ax != 0) {
    if (ax >= VF(si, vVibLength)) {
      ax = (u16)(ax - VF(si, vVibLength));
    }
    VF(si, vVibPos) = ax;
    ax = (u16)((ax >> 4) | ((ax & 0x8000u) ? 0xF000u : 0));  /* sar ax, 4 */
    ax = (u16)(ax + VF(si, vVibrato));
    ax = (u16)((u16)DataByte(ax) << 8);                           /* the table's signed byte, in the high byte */
    dx = (u16)((u32)((s32)(s16)ax * (s32)(s16)VF(si, vVibDepth)) >> 16);  /* imul: the high word */
  }
  VF(si, vOutput) = (u16)(dx + VF(si, vPitch));

  if (VF(si, vRelease) != 0) {
    VF(si, vRelease)--;
    if (VF(si, vRelease) == 0) {
      VF(si, vEnvPos) = 0x10;
      VF(si, vEnvCount) = 1;
    }
  }
  VF(si, vCount)--;
  if (VF(si, vCount) == 0) {
    DriverRunStream(si);
  }

  if (VF(si, vEnvCount) != 0) {
    VF(si, vEnvCount)--;
    if (VF(si, vEnvCount) == 0) {
      for (;;) {
        u16 entry = (u16)(VF(si, vEnvelope) + VF(si, vEnvPos));
        u16 slope = DataWord(entry);
        u16 count = DataWord((u16)(entry + 2));
        VF(si, vEnvPos) = (u16)(VF(si, vEnvPos) + 4);
        if (count != 0xFFFF) {         /* a (slope, ticks) pair */
          VF(si, vLevelStep) = slope;
          VF(si, vEnvCount) = count;
          break;
        }
        VF(si, vLevel) = slope;        /* a count of FFFFh: set the level instead */
        if (slope == 0) {
          VF(si, vLevelStep) = 0;
        }
      }
    }
  }
}

/* 08AE:1477 SpeakerStep in RES03.ASM. Step the four speaker voices, then program PIT channel 2 with the period of the first voice
   that has a nonzero level and set the gate bits from its level; the gate is closed when nothing sounds. */
static void DriverSpeakerStep(void)
{
  Voice *si;

  if (CurrentTune != 0) {
    LoudestVoice = NULL;
    VoicesLeft = SteppedVoices;
    NoteTable = SpeakerNotes;
    VoiceBase = SpeakerVoices;
    si = VoiceBase;
    do {
      if (VF(si, vCount) != 0) {
        DriverStepVoice(si);
        if (LoudestVoice == NULL && VF(si, vLevel) != 0 && VF(si, vCount) != 0) {
          LoudestVoice = si;
        }
      }
      si += VoiceWords;
      VoicesLeft--;
    } while (VoicesLeft != 0);
    if (OutputOn != 0 && LoudestVoice != NULL) {
      snd_want_tone(VF(LoudestVoice, vOutput), (u8)(VF(LoudestVoice, vLevel) & 3));
      return;
    }
  }
  snd_want_off();
}

/* 08AE:13EA TimerHandler (INT 08h), here the body of one 236.7 Hz tick: step the speaker's voices unless the driver is already
   running (LoadTune holds InService). The pump calls it. */
void DriverTick(void)
{
  if (InService == 0) {
    InService = 1;
    DriverSpeakerStep();
    InService = 0;
  }
}

/* 08AE:137C StartSoundTimer. The original hooked INT 08h and reloaded PIT channel 0 with 5041 (236.7 Hz): the backend starts the
   GIME timer, which counts the ticks and plays the tone. */
void StartSoundTimer(void)
{
  SND_ENSURE();
  snd_begin();
}

/* 08AE:13B1 StopSoundTimer. Unhook the timer, close the speaker gate (the backend stops the timer and silences the DAC). */
void StopSoundTimer(void)
{
  SND_ENSURE();
  snd_end();
}

/* SetSpeakerTune/SetTandyTune: load the four streams of row Tune of the device's table into cleared voice records
   (count 1: they start on the next tick) and make Tune current. A row entry of 0 leaves its voice alone. */
static void LoadTune(Voice *voices, u16 tune)
{
  u16 row = (u16)((u16)(tune << 3) >> 1);   /* the original indexes with a 16-bit byte offset: 8 * Tune */
  unsigned index = row;
  Voice *di = voices;

  CurrentTune = tune;
  InService = 1;
  for (VoicesLeft = SteppedVoices; VoicesLeft != 0; VoicesLeft--) {
    u16 stream = index < TuneRows * 4 ? TuneTable[index] : 0;
    if (stream != 0) {
      memset(di, 0, VoiceWords * sizeof(Voice));
      VF(di, vStream) = stream;
      VoiceTune[SteppedVoices - VoicesLeft] = (u8)tune;
      VF(di, vCount) = 1;
    }
    di += VoiceWords;
    index++;
  }
  InService = 0;
}

/* 08AE:1742 SetSpeakerTune(Tune: Word). */
void SetSpeakerTune(u16 tune)
{
  SND_ENSURE();
  LoadTune(SpeakerVoices, tune);
}

/* 08AE:17AE SetTandyTune(Tune: Word). The Tandy voices are not on the CoCo: only CurrentTune, which both devices share, is set
   (PlaySound(SoundStop) and SoundQuiet call it before SetSpeakerTune; the second call decides). */
void SetTandyTune(u16 tune)
{
  SND_ENSURE();
  CurrentTune = tune;
}

/* 08AE:181A SetSoundOutput(Enabled: Word). OutputOn := the low byte. */
void SetSoundOutput(u16 enabled)
{
  SND_ENSURE();
  OutputOn = (u8)enabled;
}
